    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    counts = [sum(v == c for row in g for v in row) for c in range(10)]
    bg = max(range(10), key=lambda c: counts[c])

    marker = None
    for r, row in enumerate(g):
        if row[0] != bg and all(v == row[0] for v in row):
            marker = ('h', r, row[0])
            break
    if marker is None:
        for c in range(w):
            vals = [g[r][c] for r in range(h)]
            if vals[0] != bg and all(v == vals[0] for v in vals):
                marker = ('v', c, vals[0])
                break
    if marker is None:
        return g

    orient, pos, marker_color = marker
    colors = [c for c in range(10) if c not in (bg, marker_color)]
    if not colors:
        return g
    obj_color = max(colors, key=lambda c: counts[c])
    pts = [(r, c) for r in range(h) for c in range(w) if g[r][c] == obj_color]
    if not pts:
        return g

    if orient == 'h':
        lo = min(r for r, c in pts)
        hi = max(r for r, c in pts)
        if pos > hi:
            delta = pos - hi - 1
            line = lo + delta - 1
        else:
            delta = pos - lo + 1
            line = hi + delta + 1
