            g[r][c] = bg
        for r, c in pts:
            nr = r + delta
            if 0 <= nr < h and g[nr][c] != marker_color:
                g[nr][c] = obj_color
        if 0 <= line < h:
            g[line] = [8] * w
    else:
        lo = min(c for r, c in pts)
