        if pos > hi:
            delta = pos - hi - 1
            line = lo + delta - 1
        else:
            delta = pos - lo + 1
            line = hi + delta + 1
        for r, c in pts:
            g[r][c] = bg
        for r, c in pts:
            nc = c + delta
            if 0 <= nc < w and g[r][nc] != marker_color:
                g[r][nc] = obj_color
        if 0 <= line < w:
            for r in range(h):
                g[r][line] = 8
    return g

